check.check-content:
Run the following script to ensure chrony is configured with an authorized timeserver: #!/usr/bin/env bash { a_output=() a_output2=() a_config_files=("/etc/chrony.conf") l_include='(confdir|sourcedir)' l_parameter_name='(server|pool)' l_parameter_value='.+' while IFS= read -r l_conf_loc; do l_dir="" l_ext="" if [ -d "$l_conf_loc" ]; then l_dir="$l_conf_loc" l_ext="*" elif grep -Psq '/\*\.([^#/
]+)?\h*$' <<< "$l_conf_loc" || [ -f "$(readlink -f "$l_conf_loc")" ]; then l_dir="$(dirname "$l_conf_loc")" l_ext="$(basename "$l_conf_loc")" fi if [[ -n "$l_dir" && -n "$l_ext" ]]; then while IFS= read -r -d $'\0' l_file_name; do [ -f "$(readlink -f "$l_file_name")" ] && a_config_files+=("$(readlink -f "$l_file_name")") done < <(find -L "$l_dir" -type f -name "$l_ext" -print0 2>/dev/null) fi done < <(awk '$1~/^\s*'"$l_include"'$/{print $2}' "${a_config_files[*]}" 2>/dev/null) for l_file in "${a_config_files[@]}"; do l_parameter_line="$(grep -Psi '^\h*'"$l_parameter_name"'(\h+|\h*:\h*)'"$l_parameter_value"' ' "$l_file")" [ -n "$l_parameter_line" ] && a_output+=(" - Parameter: "$(tr -d '()' <<< ${l_parameter_name//|/ or })"" \ " Exists in the file: "$l_file" as:" "$l_parameter_line") done [ "${#a_output[@]}" -le "0" ] && a_output2+=(" - Parameter: "$(tr -d '()' <<< ${l_parameter_name//|/ or })"" \ " Does not exist in the chrony configuration") if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" " - Reason(s) for audit failure:" "${a_output2[@]}" fi }

Rule.fixtext:
Run the following script to set mode, ownership, and group on the private SSH host key files: #!/usr/bin/env bash { a_output2=() l_ssh_group="" l_out="root" l_new_group="root" if grep -Psiq -- '^\h*ID_LIKE="?([^#
]+)? fedora ' /etc/os-release && \ grep -Psoq -- '^ssh_keys ' /etc/group; then l_ssh_group="ssh_keys" l_out="$l_ssh_group or root" l_new_group="$l_ssh_group" fi f_file_access_fix() { while IFS=: read -r l_file_mode l_file_owner l_file_group; do a_out2=() if [ "$l_file_owner" != "root" ]; then a_out2+=("" " Owned by: "$l_file_owner"" \ " should be owned by "root"" \ " Changing ownership to "root"") chown root "$l_file" fi if [ "$l_file_group" != "$l_ssh_group" ] && \ [ "$l_file_group" != "root" ]; then a_out2+=("" " Owned by group "$l_file_group"" \ " should be group owned by: "$l_out"" \ " Changing group ownership to "$l_new_group"") chgrp "$l_new_group" "$l_file" fi if [ "$(stat -Lc '%G' "$l_file")" = "$l_ssh_group" ]; then l_pmask="0137" l_change="u-x,g-wx,o-rwx" else l_pmask="0177" l_change="u-x,go-rwx" fi l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_file_mode & $l_pmask )) -gt 0 ]; then a_out2+=("" " Mode: "$l_file_mode"" \ " should be mode: "$l_maxperm" or more restrictive" \ " updating to mode: "$l_maxperm"") chmod "$l_change" "$l_file" fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=("" " - File: "$l_file"" "${a_out2[@]}") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | grep -Piq -- \ ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_access_fix fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le "0" ]; then printf '%s
' "" " - No access changes required" "" else printf '%s
' "" " - Remediation results:" "${a_output2[@]}" "" fi }

check.check-content:
Run the following script to verify SSH private host key files are owned by the root user and either: • group owned by the group ssh_keys and mode 0640 or more restrictive - OR - • group owned by the group root and mode 0600 or more restrictive #!/usr/bin/env bash { a_output=() a_output2=() l_ssh_group="" l_out="root" grep -Psiq -- '^\h*ID_LIKE="?([^#
]+)? fedora ' /etc/os-release && \ l_ssh_group="$(grep -Pso -- '^ssh_keys ' /etc/group)" && \ l_out="$l_ssh_group or $l_out" f_file_chk() { while IFS=: read -r l_fmode l_fowner l_fgroup; do a_out2=() [ "$l_fgroup" = "$l_ssh_group" ] && l_pmask="0137" || l_pmask="0177" l_maxperm="$( printf '%o' $(( 0777 & ~$l_pmask )) )" if [ $(( $l_fmode & $l_pmask )) -gt 0 ]; then a_out2+=(" - mode: "$l_fmode"" \ " should be mode: "$l_maxperm" or more restrictive") fi if [ "$l_fowner" != "root" ]; then a_out2+=(" - owned by: "$l_fowner"" \ " should be owned by "root"") fi if [ "$l_fgroup" != "$l_ssh_group" ] && [ "$l_fgroup" != "root" ]; then a_out2+=(" - group owned by: "$l_fgroup"" \ " should be group owned by: "$l_out"") fi if [ "${#a_out2[@]}" -gt "0" ]; then a_output2+=(" - File: "$l_file"" "${a_out2[@]}") else a_output+=(" - File: "$l_file" Correct:" \ " - mode: "$l_fmode"" \ " - owner: "$l_fowner"" " - group owner: "$l_fgroup"") fi done < <(stat -Lc '%#a:%U:%G' "$l_file") } while IFS= read -r -d $'\0' l_file; do if ssh-keygen -lf &>/dev/null "$l_file"; then file "$l_file" | \ grep -Piq -- ' openssh\h+([^#
]+\h+)?private\h+key ' && f_file_chk fi done < <(find -L /etc/ssh -xdev -type f -print0 2>/dev/null) if [ "${#a_output2[@]}" -le 0 ]; then printf '%s
' "" "- Audit Result:" " ** PASS **" "${a_output[@]}" "" else printf '%s
' "" "- Audit Result:" " ** FAIL **" \ " - Reason(s) for audit failure:" "${a_output2[@]}" [ "${#a_output[@]}" -gt 0 ] && \ printf '%s
' "" "- Correctly set:" "${a_output[@]}" "" fi }

